  )
  insert into public.ai_prospects(crm_client_id, entreprise, secteur, ville, commune, adresse, telephone, whatsapp, email, produits_recommandes, potentiel_fcfa, source, stage, resume_ia)
  select s.crm_id, s.entreprise, s.secteur, s.ville, s.commune, s.adresse, s.telephone, s.whatsapp, s.email, s.produits, s.potentiel, 'crm', 'enregistre', s.resume
    from src s where not exists (select 1 from public.ai_prospects p where p.crm_client_id = s.crm_id)
  on conflict do nothing;
  get diagnostics n_p = row_count;

  -- 3. Une mission par agent (arbre : président → directeur général → directeurs → responsable → superviseurs → agents)
  if exists (select 1 from public.ai_agent_tasks where type = 'instruction' and titre_norm = lower(regexp_replace(btrim('Exploiter la base CRM : transformer les prospects en rendez-vous et en ventes'), '\s+', ' ', 'g'))) then
    raise notice 'Missions déjà assignées : rien à ajouter';
  else
    create temp table crm_mt(code text primary key, id uuid) on commit drop;
  v_id := pg_temp.mk('sanix_ai_general_director', null, null, 'instruction', 'Exploiter la base CRM : transformer les prospects en rendez-vous et en ventes', 'Instruction du président. Exploiter la base CRM de SANIX AFRICA : 511 prospects répartis en 4 segments (Industrie 213, Santé 173, Immobilier 95, Logistique 30) et 8 clients. Les fiches sont dans l''entreprise IA : qualifier chaque prospect, le contacter par le canal adapté (WhatsApp, e-mail) avec validation du président avant tout envoi, obtenir des démonstrations, préparer les offres dans les tarifs du catalogue, et fidéliser les clients existants. Plan initial déjà réparti entre les directions : superviser, arbitrer et rendre compte.', '["Qualifier les 511 prospects (score /100)", "Obtenir 30 démonstrations planifiées (objectif initial, ajustable)", "Aucun message externe sans validation du président", "Fidéliser les 8 clients et suivre les 9 commandes", "Rapport quotidien de progression"]'::jsonb, 'CRM SANIX au 09/11/2026 : 511 prospects (213 Industrie → Sanix AluExpert ERP ; 173 Santé → MedicorERP ; 95 Immobilier → ImmoSuite ERP ; 30 Logistique → Angel''s) ; 486 avec téléphone dont 253 mobiles valides pour WhatsApp ; 112 avec e-mail ; 23 sans aucun moyen de contact ; 8 clients ; 9 commandes (6 en cours, 3 livrées). Les prospects sont dans l''entreprise IA (source « crm », étape « enregistre »).', 1, 30, 'attente_sous_taches', 'Plan initial : mission répartie entre les subordonnés d''après la base CRM ; reprise automatique à la fin de leurs missions.', v_pres);
  insert into pg_temp.crm_mt values ('sanix_ai_general_director', v_id);
  v_id := pg_temp.mk('sanix_ai_sales_director', 'sanix_ai_general_director', (select id from pg_temp.crm_mt where code = 'sanix_ai_general_director'), 'mission', 'Plan commercial sur la base CRM : 4 segments, 4 produits', 'Construire et superviser le plan commercial sur la base CRM : Industrie 213, Santé 173, Immobilier 95, Logistique 30. Un produit par segment : Industrie → Sanix AluExpert ERP, Santé → MedicorERP, Immobilier → ImmoSuite ERP, Logistique → Angel''s. Répartir l''effort par volume et par potentiel, suivre le pipeline et arbitrer les priorités avec le responsable de la prospection.', '["Plan de prospection par segment validé", "Objectifs de rendez-vous par segment", "Point d''avancement hebdomadaire"]'::jsonb, null, 1, 21, 'attente_sous_taches', 'Plan initial : mission répartie entre les subordonnés d''après la base CRM ; reprise automatique à la fin de leurs missions.', null);
  insert into pg_temp.crm_mt values ('sanix_ai_sales_director', v_id);
  v_id := pg_temp.mk('ia_resp_prospection', 'sanix_ai_sales_director', (select id from pg_temp.crm_mt where code = 'sanix_ai_sales_director'), 'mission', 'Organiser la prospection des 511 prospects du CRM par segment', 'Organiser la chaîne de prospection sur les 511 prospects importés du CRM : compléter les fiches, qualifier, contacter, planifier les démonstrations. Priorités : Santé (173, panier le plus élevé), Immobilier (95), puis Industrie (213) et Logistique (30). Les superviseurs conduisent les segments ; vérifier la qualité des fiches avant tout contact.', '["Plan par superviseur", "Qualité des fiches contrôlée avant contact", "Suivi hebdomadaire du taux de qualification"]'::jsonb, null, 1, 14, 'attente_sous_taches', 'Plan initial : mission répartie entre les subordonnés d''après la base CRM ; reprise automatique à la fin de leurs missions.', null);
  insert into pg_temp.crm_mt values ('ia_resp_prospection', v_id);
  v_id := pg_temp.mk('ia_sup_immo', 'ia_resp_prospection', (select id from pg_temp.crm_mt where code = 'ia_resp_prospection'), 'mission', 'Prospection du segment Immobilier : 95 prospects (ImmoSuite ERP)', 'Conduire la prospection des 95 prospects immobiliers du CRM (promoteurs agréés, sociétés civiles immobilières) pour ImmoSuite ERP : compléter, qualifier, planifier les démonstrations. Superviser le chercheur, l''analyste, le qualificateur et le responsable des rendez-vous.', '["95 fiches immobilier complètes", "Prospects qualifiés et priorisés", "Démonstrations planifiées"]'::jsonb, null, 2, 14, 'attente_sous_taches', 'Plan initial : mission répartie entre les subordonnés d''après la base CRM ; reprise automatique à la fin de leurs missions.', null);
  insert into pg_temp.crm_mt values ('ia_sup_immo', v_id);
  v_id := pg_temp.mk('ia_sup_sante', 'ia_resp_prospection', (select id from pg_temp.crm_mt where code = 'ia_resp_prospection'), 'mission', 'Prospection du segment Santé : 173 prospects (MedicorERP)', 'Conduire la prospection des 173 établissements de santé du CRM (cliniques, cabinets, laboratoires) pour MedicorERP : compléter, contacter par e-mail, préparer les offres. Respecter la confidentialité : aucune donnée de patient.', '["173 fiches santé complètes", "Premiers contacts validés", "Offres préparées pour les prospects chauds"]'::jsonb, null, 1, 14, 'attente_sous_taches', 'Plan initial : mission répartie entre les subordonnés d''après la base CRM ; reprise automatique à la fin de leurs missions.', null);
  insert into pg_temp.crm_mt values ('ia_sup_sante', v_id);
  v_id := pg_temp.mk('ia_sup_distribution', 'ia_resp_prospection', (select id from pg_temp.crm_mt where code = 'ia_resp_prospection'), 'mission', 'Prospection des segments Industrie (213) et Logistique (30)', 'Conduire la prospection des 213 ateliers et entreprises industrielles (Sanix AluExpert ERP) et des 30 sociétés de logistique (Angel''s) du CRM : compléter les fiches et engager les conversations WhatsApp sur les mobiles valides.', '["243 fiches complètes", "Conversations WhatsApp engagées (après validation)", "Retour hebdomadaire au responsable de la prospection"]'::jsonb, null, 2, 14, 'attente_sous_taches', 'Plan initial : mission répartie entre les subordonnés d''après la base CRM ; reprise automatique à la fin de leurs missions.', null);
  insert into pg_temp.crm_mt values ('ia_sup_distribution', v_id);
  v_id := pg_temp.mk('ia_hunter_1', 'ia_sup_immo', (select id from pg_temp.crm_mt where code = 'ia_sup_immo'), 'mission', 'Compléter les fiches Immobilier du CRM (95 prospects)', 'Pour chaque prospect immobilier du CRM, compléter les informations manquantes : décideur et sa fonction, site web, réseaux, activité, programmes en cours. Les décideurs ne sont renseignés pour aucun prospect. Utiliser la recherche web, citer la source, ne jamais contacter.', '["Décideur identifié pour au moins 50 % des fiches", "Sources citées", "Aucun doublon créé"]'::jsonb, 'CRM SANIX au 09/11/2026 : 511 prospects (213 Industrie → Sanix AluExpert ERP ; 173 Santé → MedicorERP ; 95 Immobilier → ImmoSuite ERP ; 30 Logistique → Angel''s) ; 486 avec téléphone dont 253 mobiles valides pour WhatsApp ; 112 avec e-mail ; 23 sans aucun moyen de contact ; 8 clients ; 9 commandes (6 en cours, 3 livrées). Les prospects sont dans l''entreprise IA (source « crm », étape « enregistre »).', 2, 10, 'a_faire', null, null);
  insert into pg_temp.crm_mt values ('ia_hunter_1', v_id);
  v_id := pg_temp.mk('ia_enrich_1', 'ia_sup_immo', (select id from pg_temp.crm_mt where code = 'ia_sup_immo'), 'mission', 'Fiabiliser les coordonnées du CRM : 23 prospects sans contact, numéros à corriger', 'Sur l''ensemble des 511 prospects du CRM : retrouver un moyen de contact pour les 23 fiches qui n''en ont aucun, corriger et normaliser les numéros qui ne sont pas des mobiles valides (233 sur 486), repérer les doublons (même numéro ou même e-mail) et les e-mails invalides.', '["Moyen de contact trouvé pour les 23 fiches vides (si disponible publiquement)", "Numéros normalisés (indicatif +225)", "Liste des doublons transmise au superviseur"]'::jsonb, 'CRM SANIX au 09/11/2026 : 511 prospects (213 Industrie → Sanix AluExpert ERP ; 173 Santé → MedicorERP ; 95 Immobilier → ImmoSuite ERP ; 30 Logistique → Angel''s) ; 486 avec téléphone dont 253 mobiles valides pour WhatsApp ; 112 avec e-mail ; 23 sans aucun moyen de contact ; 8 clients ; 9 commandes (6 en cours, 3 livrées). Les prospects sont dans l''entreprise IA (source « crm », étape « enregistre »).', 2, 10, 'a_faire', null, null);
  insert into pg_temp.crm_mt values ('ia_enrich_1', v_id);
  v_id := pg_temp.mk('ia_qualif_1', 'ia_sup_immo', (select id from pg_temp.crm_mt where code = 'ia_sup_immo'), 'mission', 'Qualifier les prospects du CRM (score /100), segment Immobilier d''abord', 'Qualifier les prospects du CRM avec la grille /100 (produit 25, besoin 20, finance 15, décideur 15, court terme 15, disponibilité 10), en commençant par les 95 prospects immobiliers puis la Santé (173). Recommander le produit adapté (un par segment) et classer par priorité. Marquer comme hors cible tout prospect sans rapport avec le catalogue.', '["Au moins 100 prospects qualifiés la première semaine", "Score justifié pour chaque critère", "Liste des prospects prioritaires (score ≥ 80)"]'::jsonb, 'CRM SANIX au 09/11/2026 : 511 prospects (213 Industrie → Sanix AluExpert ERP ; 173 Santé → MedicorERP ; 95 Immobilier → ImmoSuite ERP ; 30 Logistique → Angel''s) ; 486 avec téléphone dont 253 mobiles valides pour WhatsApp ; 112 avec e-mail ; 23 sans aucun moyen de contact ; 8 clients ; 9 commandes (6 en cours, 3 livrées). Les prospects sont dans l''entreprise IA (source « crm », étape « enregistre »).', 1, 10, 'a_faire', null, null);
  insert into pg_temp.crm_mt values ('ia_qualif_1', v_id);
  v_id := pg_temp.mk('ia_rdv_1', 'ia_sup_immo', (select id from pg_temp.crm_mt where code = 'ia_sup_immo'), 'mission', 'Planifier les démonstrations avec les prospects qui répondent', 'Dès que des prospects répondent aux premiers contacts, proposer des créneaux dans les disponibilités des commerciaux, planifier les démonstrations, confirmer par écrit la veille et reprogrammer en cas d''absence.', '["Créneaux proposés sous 2 h", "Rendez-vous confirmés la veille", "Taux de présence suivi"]'::jsonb, 'CRM SANIX au 09/11/2026 : 511 prospects (213 Industrie → Sanix AluExpert ERP ; 173 Santé → MedicorERP ; 95 Immobilier → ImmoSuite ERP ; 30 Logistique → Angel''s) ; 486 avec téléphone dont 253 mobiles valides pour WhatsApp ; 112 avec e-mail ; 23 sans aucun moyen de contact ; 8 clients ; 9 commandes (6 en cours, 3 livrées). Les prospects sont dans l''entreprise IA (source « crm », étape « enregistre »).', 3, 21, 'a_faire', null, null);
