  v_id := pg_temp.mk('ia_hunter_2', 'ia_sup_sante', (select id from pg_temp.crm_mt where code = 'ia_sup_sante'), 'mission', 'Compléter les fiches Santé du CRM (173 prospects)', 'Pour chaque établissement de santé du CRM, compléter : directeur ou responsable, spécialités, taille, site web. Les décideurs ne sont renseignés pour aucun prospect. Utiliser la recherche web, citer la source, ne jamais contacter, aucune donnée de patient.', '["Directeur identifié pour au moins 50 % des fiches", "Spécialités renseignées", "Sources citées"]'::jsonb, 'CRM SANIX au 09/11/2026 : 511 prospects (213 Industrie → Sanix AluExpert ERP ; 173 Santé → MedicorERP ; 95 Immobilier → ImmoSuite ERP ; 30 Logistique → Angel''s) ; 486 avec téléphone dont 253 mobiles valides pour WhatsApp ; 112 avec e-mail ; 23 sans aucun moyen de contact ; 8 clients ; 9 commandes (6 en cours, 3 livrées). Les prospects sont dans l''entreprise IA (source « crm », étape « enregistre »).', 2, 10, 'a_faire', null, null);
  insert into pg_temp.crm_mt values ('ia_hunter_2', v_id);
  v_id := pg_temp.mk('ia_mail_1', 'ia_sup_sante', (select id from pg_temp.crm_mt where code = 'ia_sup_sante'), 'mission', 'Premier contact par e-mail des prospects du CRM avec adresse valide (112)', 'Pour les 112 prospects du CRM disposant d''une adresse e-mail valide, rédiger un premier contact personnalisé (segment, produit adapté, bénéfice concret) avec lien de désinscription. Chaque envoi passe par la validation du président. Commencer par les prospects les mieux qualifiés.', '["Messages personnalisés par segment", "Envois soumis à validation", "Réponses suivies et transmises au responsable des rendez-vous"]'::jsonb, 'CRM SANIX au 09/11/2026 : 511 prospects (213 Industrie → Sanix AluExpert ERP ; 173 Santé → MedicorERP ; 95 Immobilier → ImmoSuite ERP ; 30 Logistique → Angel''s) ; 486 avec téléphone dont 253 mobiles valides pour WhatsApp ; 112 avec e-mail ; 23 sans aucun moyen de contact ; 8 clients ; 9 commandes (6 en cours, 3 livrées). Les prospects sont dans l''entreprise IA (source « crm », étape « enregistre »).', 2, 14, 'a_faire', null, null);
